head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.isUpdate = false;
scwin.storageId = "";

// 수정 여부

///////// 2. 초기화 영역 /////////
            scwin.onpageload = function () {

                scwin.storageId = $c.data.getParameter("storageId");

                const formUpclssCd = $c.data.getParameter("formUpclssCd");
                if (!$c.util.isEmpty(formUpclssCd)) {                    
                    dma_save.set("formUpclssCd", formUpclssCd);
                    dma_save.set("formUpclssNm", $c.data.getParameter("formUpclssNm"));
                    dma_save.set("formUpclssEngNm", $c.data.getParameter("formUpclssEngNm"));

                    ibx_formUpclssCd.setDisabled(true);
                    btn_save.setValue("변경 저장");
                    scwin.isUpdate = true;
                }
            };

///////// 3. 컴포넌트 이벤트 영역 /////////
            scwin.ibx_formUpclssEngNm_onkeyup = function (e) {

                $c.tms.disableBlockKor(ibx_formUpclssEngNm);
            };

            scwin.ibx_formUpclssCd_onkeyup = function (e) {

                $c.tms.disableBlockKor(ibx_formUpclssCd);
                // 양수만 되게 수정
                ibx_formUpclssCd.setValue((ibx_formUpclssCd.getValue()).replace(/[^0-9]/g, ""));
            };

            scwin.btn_save_onclick = async function (e) {

                // validation 체크
                if (!$c.tms.validateGroupTms("grp_input")) return;

                if (scwin.isUpdate) {                                           
                    $c.sbm.setAction(sbm_save, "/api/code/form-upclss/update/" + dma_save.get("formUpclssCd"));
                }
                // 이중 클릭 방지
                btn_save.setDisabled(true);                
                // 코드 정보 저장
                $c.sbm.execute(sbm_save, dma_save.getJSON());                
            };

            scwin.btn_close_onclick = function (e) {

                $c.win.closePopup();
            };

///////// 4. 서브미션 콜백 영역 /////////
            scwin.sbm_save_submitdone = async function (e) {

                const result = e.responseJSON;
                if (result.success) {
                    await $c.win.alert("저장 되었습니다.");

                    let params = {};
                    params.refreshYn = "Y";
                    params.storageId = scwin.storageId;

                    $c.win.closePopup(params);
                } else {
                    $c.win.alert(result.message);
                }
                // 이중 클릭 해제
                btn_save.setDisabled(false);
            };
